fields.InputDefinition:
{
  "goal": "Open the 'Products' entity grid — type 'Products' in the LEFT sidebar 'Search entities...' box and click it (or navigate to http://localhost:4200/app/data-explorer/Data?entity=Products). Wait for the grid to load. Click 'Configure view settings' (the sliders icon in the grid toolbar) to open the Configure View panel, then select its 'Filters' tab. Verify the advanced filter builder UI renders — it offers filter modes (e.g. Simple / Advanced / Smart) and inputs to build a condition (field / operator / value). Seeing the filter builder render in the Filters tab is success — you do NOT need to fully apply a filter, and no error should appear. Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "The Configure View panel's 'Filters' tab was opened",
    "The advanced filter builder UI rendered (filter mode options like Simple/Advanced/Smart and/or field/operator/value inputs)",
    "No error messages or crash pages"
  ]
}
